package com.sodi.metareports.client.dto; import com.sodi.metareports.client.entity.ClientStatus; import jakarta.validation.constraints.*;
public class ClientForm { @NotBlank @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9_-]{1,29}") private String code; @NotBlank @Size(max=160) private String commercialName; @Size(max=200) private String legalName; @Size(max=1000) private String description; @NotNull private ClientStatus status=ClientStatus.PILOT; @NotBlank @Pattern(regexp="[A-Za-z]{3}") private String primaryCurrency="GTQ"; @NotBlank private String timezone="America/Guatemala";
 public String getCode(){return code;} public void setCode(String v){code=v;} public String getCommercialName(){return commercialName;} public void setCommercialName(String v){commercialName=v;} public String getLegalName(){return legalName;} public void setLegalName(String v){legalName=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public ClientStatus getStatus(){return status;} public void setStatus(ClientStatus v){status=v;} public String getPrimaryCurrency(){return primaryCurrency;} public void setPrimaryCurrency(String v){primaryCurrency=v;} public String getTimezone(){return timezone;} public void setTimezone(String v){timezone=v;}}
